#include <LiquidCrystal.h>
#include <math.h>

// ========================================
// SMART GREENHOUSE - PID CONTROL
// ========================================

// LCD: RS, E, D4, D5, D6, D7
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

// Arduino pins
const byte LM35_PIN   = A0;
const byte HEATER_PIN = 9;
const byte FAN_PIN    = 10;

// Temperature settings
const double SETPOINT   = 25.0;
const double LOWER_LIMIT = 24.0;
const double UPPER_LIMIT = 26.0;

// PID parameters
double Kp = 30.0;
double Ki = 0.25;
double Kd = 2.0;

// PID variables
double integral = 0.0;
double previousError = 0.0;

// Temperature variables
double ambientTemperature = 0.0;
double simulatedTemperature = 0.0;

// Actuator outputs
int heaterPWM = 0;
int fanPWM = 0;

// Timing
unsigned long previousControlTime = 0;
unsigned long previousDisplayTime = 0;

const unsigned long CONTROL_INTERVAL = 100;
const unsigned long DISPLAY_INTERVAL = 300;

// Thermal model parameters
const double HEATING_RATE = 0.12;
const double FAN_COOLING_RATE = 0.15;
const double PASSIVE_LOSS = 0.015;

// ========================================
// Read LM35
// ========================================

double readLM35() {
  int rawValue = analogRead(LM35_PIN);

  double voltage = rawValue * (5.0 / 1023.0);

  // LM35 sensitivity: 10 mV per degree C
  return voltage * 100.0;
}

// ========================================
// Setup
// ========================================

void setup() {
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);

  analogWrite(HEATER_PIN, 0);
  analogWrite(FAN_PIN, 0);

  lcd.begin(16, 2);
  lcd.clear();

  lcd.setCursor(0, 0);
  lcd.print("Greenhouse PID");

  lcd.setCursor(0, 1);
  lcd.print("Initializing");

  delay(1500);

  // Read initial temperature from LM35
  ambientTemperature = readLM35();

  // Initialize simulated temperature
  simulatedTemperature = ambientTemperature;

  previousControlTime = millis();
  previousDisplayTime = millis();

  lcd.clear();
}

// ========================================
// Main Loop
// ========================================

void loop() {
  unsigned long now = millis();

  // ======================================
  // PID CONTROL
  // ======================================

  if (now - previousControlTime >= CONTROL_INTERVAL) {

    double dt =
      (now - previousControlTime) / 1000.0;

    previousControlTime = now;

    // Error from target temperature
    double error = SETPOINT - simulatedTemperature;

    // Integral term
    integral += error * dt;
    integral = constrain(integral, -100.0, 100.0);

    // Derivative term
    double derivative = 0.0;

    if (dt > 0.0) {
      derivative = (error - previousError) / dt;
    }

    previousError = error;

    // PID output
    double pidOutput =
      Kp * error +
      Ki * integral +
      Kd * derivative;

    pidOutput = constrain(pidOutput, -255.0, 255.0);

    // ====================================
    // TEMPERATURE CONTROL
    // ====================================

    // Inside the acceptable temperature range
    if (simulatedTemperature >= LOWER_LIMIT &&
        simulatedTemperature <= UPPER_LIMIT) {

      heaterPWM = 0;
      fanPWM = 0;

      integral = 0.0;
      previousError = 0.0;
    }

    // Below 24 C: activate heater
    else if (simulatedTemperature < LOWER_LIMIT) {

      heaterPWM = (int)constrain(pidOutput, 0.0, 255.0);
      fanPWM = 0;
    }

    // Above 26 C: activate fan
    else if (simulatedTemperature > UPPER_LIMIT) {

      heaterPWM = 0;
      fanPWM = (int)constrain(-pidOutput, 0.0, 255.0);
    }

    // Safety fallback
    else {
      heaterPWM = 0;
      fanPWM = 0;
    }

    // Apply outputs
    analogWrite(HEATER_PIN, heaterPWM);
    analogWrite(FAN_PIN, fanPWM);

    // ====================================
    // THERMAL MODEL SIMULATION
    // ====================================

    double heaterEffect =
      HEATING_RATE * (heaterPWM / 255.0);

    double fanEffect =
      FAN_COOLING_RATE * (fanPWM / 255.0);

    double passiveEffect =
      PASSIVE_LOSS *
      (simulatedTemperature - ambientTemperature);

    // Update simulated temperature
    simulatedTemperature +=
      (heaterEffect - fanEffect - passiveEffect) * dt;

    simulatedTemperature =
      constrain(simulatedTemperature, -20.0, 100.0);
  }

  // ======================================
  // LCD DISPLAY
  // ======================================

  if (now - previousDisplayTime >= DISPLAY_INTERVAL) {

    previousDisplayTime = now;

    // Display temperature
    lcd.setCursor(0, 0);
    lcd.print("Temp:");
    lcd.print(simulatedTemperature, 1);
    lcd.write(byte(223));
    lcd.print("C   ");

    // Display operating state
    lcd.setCursor(0, 1);

    if (heaterPWM > 0) {
      lcd.print("HEATING PWM:");
      lcd.print(heaterPWM);
      lcd.print(" ");
    }
    else if (fanPWM > 0) {
      lcd.print("COOLING PWM:");
      lcd.print(fanPWM);
      lcd.print(" ");
    }
    else {
      lcd.print("TEMP IN RANGE  ");
    }
  }
}
